 @override void initState(){super.initState();load();} Future<void> load()async{rows=await repo.templates();if(mounted)setState(()=>loading=false);}
 Future<void> edit([Map<String,dynamic>? t])async{final title=TextEditingController(text:t?['title']?.toString()??'');final body=TextEditingController(text:t?['body']?.toString()??'');String type=t?['document_type']?.toString()??'personalizado';await showDialog(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:Text(t==null?'Criar Modelo de Documento':'Editar Modelo de Documento'),content:SizedBox(width:600,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Título')),DropdownButtonFormField<String>(initialValue:type,items:const [DropdownMenuItem(value:'contrato',child:Text('Contrato de Mútuo')),DropdownMenuItem(value:'recibo',child:Text('Recibo de Pagamento')),DropdownMenuItem(value:'compromisso',child:Text('Compromisso de Pagamento')),DropdownMenuItem(value:'personalizado',child:Text('Personalizado'))],onChanged:(v){if(v==null)return;setD(()=>type=v);if(body.text.isEmpty)body.text=examples[v]??'';},decoration:const InputDecoration(labelText:'Tipo')),TextField(controller:body,minLines:12,maxLines:20,decoration:const InputDecoration(labelText:'Texto do modelo',hintText:'Use {{cliente_nome}}, {{cliente_documento}}, {{cliente_endereco}}, {{capital}}, {{total}}, {{juros}}, {{parcelas}}, {{data}}'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton(onPressed:()async{if(title.text.trim().isEmpty)return;await repo.saveTemplate(id:t?['id']?.toString(),title:title.text.trim(),type:type,body:body.text);if(c.mounted)Navigator.pop(c);await load();},child:const Text('Salvar'))])));}
 Future<void> generate(Map<String,dynamic> t)async{final customers=await repo.customers();if(!mounted)return;if(customers.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Cadastre um cliente antes de gerar o documento.')));return;}Map<String,dynamic>? customer;Map<String,dynamic>? loan;List<Map<String,dynamic>> loans=[];String text=t['body']?.toString()??'';final editor=TextEditingController(text:text);String clientSig='',responsibleSig='',witnessSig='';await showDialog(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:Text('Gerar — ${t['title']}'),content:SizedBox(width:650,child:SingleChildScrollView(child:Column(children:[DropdownButtonFormField<Map<String,dynamic>>(items:customers.map((x)=>DropdownMenuItem(value:x,child:Text(x['name']?.toString()??'Cliente'))).toList(),onChanged:(v)async{customer=v;loan=null;loans=v==null?[]:await repo.loans(v['id'].toString());setD((){});},decoration:const InputDecoration(labelText:'Cliente')),DropdownButtonFormField<Map<String,dynamic>>(value:loan,items:loans.map((x)=>DropdownMenuItem(value:x,child:Text('Empréstimo R$ ${x['principal']}'))).toList(),onChanged:(v)=>setD(()=>loan=v),decoration:const InputDecoration(labelText:'Empréstimo')),const SizedBox(height:8),TextField(controller:editor,minLines:12,maxLines:18,decoration:const InputDecoration(labelText:'Texto livre antes de gerar')),TextField(onChanged:(v)=>clientSig=v,decoration:const InputDecoration(labelText:'Assinatura do cliente')),TextField(onChanged:(v)=>responsibleSig=v,decoration:const InputDecoration(labelText:'Assinatura do responsável')),TextField(onChanged:(v)=>witnessSig=v,decoration:const InputDecoration(labelText:'Assinatura da testemunha (se aplicável)'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton.icon(icon:const Icon(Icons.picture_as_pdf),label:const Text('Gerar'),onPressed:customer==null?null:()async{String out=editor.text;final repl={'{{cliente_nome}}':customer?['name']??'','{{cliente_documento}}':customer?['document']??'','{{cliente_endereco}}':customer?['address']??'','{{capital}}':loan?['principal']?.toString()??'','{{total}}':loan?['total_amount']?.toString()??'','{{juros}}':loan?['interest_rate']?.toString()??'','{{parcelas}}':loan?['installments']?.toString()??'','{{data}}':DateTime.now().toString().substring(0,10)};repl.forEach((k,v)=>out=out.replaceAll(k,v.toString()));await repo.saveGenerated(templateId:t['id']?.toString(),customerId:customer?['id']?.toString(),loanId:loan?['id']?.toString(),title:t['title'].toString(),body:out,clientSignature:clientSig,responsibleSignature:responsibleSig,witnessSignature:witnessSig);final pdf=pw.Document();pdf.addPage(pw.MultiPage(pageFormat:PdfPageFormat.a4,build:(_)=>[pw.Text(t['title'].toString(),style:pw.TextStyle(fontSize:18,fontWeight:pw.FontWeight.bold)),pw.SizedBox(height:18),pw.Text(out),pw.SizedBox(height:36),pw.Text('Assinatura do cliente: $clientSig'),pw.Text('Responsável: $responsibleSig'),if(witnessSig.isNotEmpty)pw.Text('Testemunha: $witnessSig')]));if(c.mounted)Navigator.pop(c);await Printing.layoutPdf(onLayout:(_)=>pdf.save(),name:'${t['title']}.pdf');})])));}
 Future<void> help()async=>showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Tutorial de Criação de Documentos'),content:const Text('Crie um modelo novo ou clone um existente. Edite o texto e use os campos automáticos indicados. Ao usar um modelo, selecione cliente e empréstimo, revise o texto, informe as assinaturas quando aplicável e toque em Gerar para criar o documento pronto para impressão ou salvamento.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Fechar'))]));
 @override Widget build(BuildContext context)=>loading?const Center(child:CircularProgressIndicator()):Scaffold(body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[const Expanded(child:Text('Modelos de Documentos',style:TextStyle(fontSize:25,fontWeight:FontWeight.w900))),IconButton(tooltip:'Ajuda',onPressed:help,icon:const Icon(Icons.help_outline))]),const Text('Crie, edite, clone, compartilhe e gere documentos com dados de clientes e empréstimos.'),const SizedBox(height:12),FilledButton.icon(onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('Criar Modelo de Documento')),const SizedBox(height:12),if(rows.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(24),child:Text('Nenhum modelo personalizado. Crie um modelo para começar.'))),for(final t in rows)Card(child:ListTile(title:Text(t['title']?.toString()??'Modelo'),subtitle:Text(t['document_type']?.toString()??'personalizado'),trailing:PopupMenuButton<String>(onSelected:(a)async{if(a=='usar')await generate(t);if(a=='editar')await edit(t);if(a=='clonar'){await repo.cloneTemplate(t);await load();}if(a=='excluir'){await repo.deleteTemplate(t['id'].toString());await load();}if(a=='compartilhar'){await generate(t);}},itemBuilder:(_)=>const [PopupMenuItem(value:'usar',child:Text('Usar modelo')),PopupMenuItem(value:'editar',child:Text('Editar modelo')),PopupMenuItem(value:'clonar',child:Text('Clonar modelo')),PopupMenuItem(value:'compartilhar',child:Text('Compartilhar modelo')),PopupMenuItem(value:'excluir',child:Text('Excluir modelo'))]))))])));
